'use strict';
const DATA=JSON.parse(document.getElementById('atlas-data').textContent);
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===null||v===undefined?'—':Number(v).toLocaleString('en-IN');
const title=s=>String(s).split(' ').map(w=>w.length<=2?w.toUpperCase():w[0].toUpperCase()+w.slice(1).toLowerCase()).join(' ');
const baseColors={BJP:'#ff8000',INC:'#00bfff',AAP:'#dfc665',SP:'#ed7373',AITC:'#20d49a','CPI(M)':'#ff1028',CPI:'#ff1028',TDP:'#ffe13c',JSP:'#e47b91',YSRCP:'#87b7dc',DMK:'#ff4f7a',AIADMK:'#32d692',TVK:'#c9a26c',BRS:'#cf8fbd',JMM:'#6cb799',BJD:'#9bc67e','JD(U)':'#b2d38d',RJD:'#6eaf85',NDPP:'#9dbbd1',NPP:'#cebf80',SKM:'#cd8596',MNF:'#86aacb',ZPM:'#ce9e75',JKNC:'#c57e83',SHS:'#dfac70','SHS(UBT)':'#b48ece',NCP:'#8fa4d0','NCP(SP)':'#9e86cd',IUML:'#69b690',IND:'#9aa4a0',NOTA:'#596659',UDF:'#00bfff',LDF:'#ff1028',NDA:'#ff8000',OTHER:'#9aa4a0'};
const palette=['#b5a1d9','#80b9ad','#cbb77d','#c48d9b','#96bbd0','#b8bfa0','#d5a186'];
function color(p){if(baseColors[p])return baseColors[p];if(p==='INDIA'||p==='Congress-led UPA'||p==='Congress-led alliance'||p==='Maha Vikas Aghadi'||p==='Mahagathbandhan')return '#00bfff';if(p==='NDA'||p.includes('BJP')||p==='Mahayuti'||p==='AIADMK-led NDA')return '#ff8000';if(p.includes('DMK'))return '#ff4f7a';if(baseColors[p])return baseColors[p];let h=0;for(const c of p)h=(h*31+c.charCodeAt(0))>>>0;return palette[h%palette.length]}
const groupLabel=p=>p==='IND'?'Independent':p==='NDA'?'BJP / NDA':p;
const chip=p=>`<span ${DATA.guide.some(g=>g.party===p)||['NDA','UDF','LDF','INDIA'].includes(p)?`role="link" tabindex="0" data-party-jump="${esc(p)}"`:''} class="party-chip" style="--accent:${color(p)}" title="${esc(DATA.partyNames[p]||p)}">${esc(groupLabel(p))}</span>`;
let current=null,selected=null,grouping='party',mapMode='winner',detailTab='results',pageSize=60;
let activeVersions={},nationalYear='2024',chamber='national';
const latestStates=DATA.states;
let allSeats=DATA.states.flatMap(state=>Object.values(state.seats).map(seat=>{seat.state=state.code;seat.year=state.year;seat.totalVotes=seat.partialCandidates?null:seat.candidates.reduce((n,c)=>n+c.votes,0);seat.winner=seat.candidates.find(c=>c.party!=='NOTA');seat.runner=seat.candidates.filter(c=>c.party!=='NOTA')[1]||null;seat.unopposed=!seat.runner&&seat.winner.votes===0;seat.margin=seat.runner?seat.winner.votes-seat.runner.votes:null;seat.marginPct=seat.margin!==null&&seat.totalVotes?seat.margin/seat.totalVotes*100:null;return seat}));
const getState=code=>code==='LS'?DATA.national[nationalYear]:(activeVersions[code]||latestStates.find(s=>s.code===code));
const seats=()=>current?Object.values(current.seats):allSeats;
const keyFor=c=>grouping==='alliance'?(c.coalition||c.alliance||c.party):c.party;
function shares(candidates,basis='votes'){const total=candidates.reduce((n,c)=>n+(c[basis]||0),0);if(!total)return null;const out={};for(const c of candidates){const k=keyFor(c);out[k]=(out[k]||0)+(c[basis]||0)/total*100}return out}
function statCounts(state,group=false){const out={};for(const seat of Object.values(state.seats)){const k=group?(seat.winner.coalition||seat.winner.alliance||seat.winner.party):seat.winner.party;out[k]=(out[k]||0)+1}return Object.entries(out).sort((a,b)=>b[1]-a[1])}
function prevSeat(s){return current?.previous[s.id]||null}
function delta(s,k){if(s.partialCandidates)return null;if($('#baseline').value==='2024'){const n=DATA.kerala.national[s.id];if(!n||grouping!=='alliance')return null;const now=shares(s.candidates,'evm');return now&&n.totals.total?((now[k]||0)-(n.totals[k]||0)/n.totals.total*100):null}if(!s.previousMatched)return null;const old=shares(prevSeat(s).candidates),now=shares(s.candidates);if(grouping==='alliance'&&k==='INDIA'&&!(k in (old||{})))return null;return old&&now?(now[k]||0)-(old[k]||0):null}
const signed=v=>v===null?'Unavailable':`${v>=0?'+':''}${v.toFixed(1)} pp`;
const shareText=s=>s.totalVotes?`${(s.winner.votes/s.totalVotes*100).toFixed(1)}%`:'—';
function downloadFile(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function bounds(paths){let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const p of paths){const nums=p.match(/-?\d+(?:\.\d+)?/g)?.map(Number)||[];for(let i=0;i<nums.length;i+=2){minX=Math.min(minX,nums[i]);maxX=Math.max(maxX,nums[i]);minY=Math.min(minY,nums[i+1]);maxY=Math.max(maxY,nums[i+1])}}if(!Number.isFinite(minX))return '0 0 100 100';const pad=Math.max(maxX-minX,maxY-minY)*.06;return `${minX-pad} ${minY-pad} ${maxX-minX+2*pad} ${maxY-minY+2*pad}`}
function country(){const statePaths=DATA.states.map(s=>`<path d="${s.countryPath}" fill="${color(s.largest)}" data-state="${s.code}" role="button" tabindex="0" aria-label="Explore ${esc(s.name)} ${s.year}"><title>${esc(s.name)} · ${s.year} · ${esc(s.largest)} ${s.counts[s.largest]}/${s.total} seats</title></path>`).join('');$('#india-map').innerHTML=DATA.nationalMap.map(m=>`<path d="${m.path}" fill="#3d493b" style="cursor:default"><title>${esc(m.name)} · no elected legislative assembly</title></path>`).join('')+statePaths;$('#india-map').setAttribute('viewBox',bounds([...DATA.states.map(s=>s.countryPath),...DATA.nationalMap.map(x=>x.path)]));const leaders=[...new Set(DATA.states.map(s=>s.largest))];$('#country-legend').innerHTML=leaders.map(p=>`<span style="color:${color(p)}">● ${esc(p)}</span>`).join('')+'<span style="color:#899783">● No assembly</span>';renderStateList();$('#national-candidate-count').textContent=fmt(DATA.states.reduce((n,s)=>n+(s.candidateCount||Object.values(s.seats).reduce((a,b)=>a+b.candidates.length,0)),0));$('#state-picker').insertAdjacentHTML('beforeend',DATA.states.map(s=>`<option value="${s.code}">${esc(s.name)} · ${s.year}</option>`).join(''))}
function renderStateList(){const q=$('#state-search').value.toLowerCase().trim(),list=DATA.states.filter(s=>`${s.name} ${s.year} ${s.largest}`.toLowerCase().includes(q));$('#state-list').innerHTML=list.map(s=>`<button class="state-item" data-state="${s.code}"><span class="state-code">${s.code}</span><span><strong>${esc(s.name)}</strong><small>${s.year} assembly election · ${s.total} seats</small></span><span class="leader" style="color:${color(s.largest)}">${esc(s.largest)}<small>${s.counts[s.largest]} seats · largest party ↗</small></span></button>`).join('')||'<p class="note">No matching states.</p>'}
function selectStateBase(code,id=null,scroll=true){current=getState(code)||null;$('#state-picker').value=current?current.code:'IN';$('#india-view').hidden=!!current;$('#state-view').hidden=!current;$('#search').value='';$('#party-filter').value='';$('#sort').value='number';mapMode='winner';detailTab='results';grouping=current?.coalitionReviewed?'alliance':'party';pageSize=60;if(current){selected=id&&current.seats[id]?id:(current.code==='KL'?'48':Object.keys(current.seats)[0]);renderState()}else{document.title='India Votes';selected=null;$('#region').innerHTML='<option value="">All states</option>'+DATA.states.map(s=>`<option value="${s.code}">${esc(s.name)}</option>`).join('');setPartyFilter();renderTable()}$('#races-title').textContent=`Constituency results · ${current?current.name:'India'}`;history.replaceState(null,'',current?`#state=${current.code}&seat=${selected}`:'#india');if(scroll)window.scrollTo({top:0,behavior:'smooth'})}
function mapColor(s){if(mapMode==='shift'){const v=delta(s,$('#shift-party').value);return v===null?'#4c584a':v>=0?`color-mix(in srgb,#00bfff ${25+Math.min(Math.abs(v)*3,75)}%,#273527)`:`color-mix(in srgb,#ff1028 ${25+Math.min(Math.abs(v)*3,75)}%,#273527)`}if(mapMode==='margin')return s.marginPct===null?'#65765d':`color-mix(in srgb,${color(keyFor(s.winner))} ${25+Math.min(s.marginPct*2,75)}%,#273527)`;return color(keyFor(s.winner))}
function chooseSeat(id,scroll=false){if(!current?.seats[id])return;selected=id;renderDetail();renderMap();history.replaceState(null,'',`#chamber=${chamber}&state=${current.code}&year=${current.year}&seat=${id}`);if(scroll)$('#detail').scrollIntoView({behavior:'smooth',block:'start'})}
function nationalComparison(s){const n=DATA.kerala.national[s.id];if(!n)return '<div class="empty"><strong>2024 national comparison</strong>Loaded for Ponnani parliamentary segments AC 43–49. This seat has no imported national comparison.</div>';const now=shares(s.candidates,'evm');if(grouping!=='alliance')return '<div class="empty"><strong>2024 national comparison</strong>Switch to Coalitions to compare the UDF, LDF and NDA across elections.</div>';return `<div class="national-comparison"><h3>2024 national → 2026 state</h3><p class="small">Same assembly segment · EVM votes only, including NOTA</p>${['UDF','LDF','NDA'].map(k=>{const pct=n.totals[k]/n.totals.total*100;return `<div class="chart-label"><span>${chip(k)} · 2024 ${pct.toFixed(1)}%</span><strong>${signed((now[k]||0)-pct)}</strong></div>`}).join('')}<p class="note">Postal votes are excluded on both sides because 2024 parliamentary postal ballots were not assigned to assembly segments. Different elections and candidates; this is not a forecast.</p><a class="small" href="${esc(n.source)}" target="_blank" rel="noopener">Official 2024 Form 20 ↗</a></div>`}
function pastView(s){let html=`<h3 class="mini-heading">PREVIOUS ${current.code==='LS'?'NATIONAL':'STATE'} ELECTION · ${current.previousYear||'not loaded'}</h3>${current.historyNote?`<p class="note">${esc(current.historyNote)}</p>`:''}`;const prev=prevSeat(s);if(!current.previousComparable)html+='<div class="empty"><strong>Boundaries changed</strong>Seat-level shifts are disabled after delimitation. Previous and current constituency numbers do not identify comparable electorates.</div>';else if(!s.previousMatched)html+='<div class="empty"><strong>No verified seat match</strong>The previous record is missing or its constituency name could not be matched. No shift is calculated.</div>';else{const old=shares(prev.candidates),now=shares(s.candidates);html+=prev.candidates.slice(0,4).map(c=>`<div class="historical-candidate"><span>${chip(c.party)} ${esc(title(c.name))}</span><strong>${fmt(c.votes)}</strong></div>`).join('');if(now&&old&&!s.partialCandidates){const keys=[...new Set([...Object.keys(old),...Object.keys(now)])].filter(p=>p!=='NOTA').sort((a,b)=>(now[b]||0)-(now[a]||0)).slice(0,6);html+='<h3 class="mini-heading">VOTE SHARE SHIFT</h3>'+keys.map(k=>`<div class="chart-label"><span>${chip(k)}</span><span>${(old[k]||0).toFixed(1)}% → ${(now[k]||0).toFixed(1)}% · <strong>${signed((now[k]||0)-(old[k]||0))}</strong></span></div>`).join('')+'<p class="note">Percentage-point change in recorded vote share, including NOTA in both denominators. Party labels are normalised; Kerala alliance membership follows each election. Coalition and party splits can limit interpretation.</p>'}}
 if(current.code==='KL'&&current.year===2026)html+=nationalComparison(s);html+='<div class="empty"><strong>Local / panchayat elections</strong>Not imported. Ward boundaries and multiple election tiers need a separate geographic match; no totals are inferred.</div>';return html}
function peopleView(s){if(current.code!=='KL')return '<h3 class="mini-heading">WHO LIVES HERE</h3><div class="empty"><strong>Demographics not loaded for this state</strong>Resident age, gender, religion and caste are not inferred from candidate results or voting patterns. Kerala includes a sourced Census-based comparison.</div>';const d=DATA.kerala.religion.constituencies[s.id],india={hindu:79.8,muslim:14.2,christian:2.3};return `<h3 class="mini-heading">RESIDENTS · CENSUS 2011</h3><p class="note">Community-archive aggregation to assembly boundaries, not an official 2026 constituency survey. Grey bars compare the constituency estimate with India, both using Census 2011. Describes residents, not voting behaviour.</p>${d.source==='district-urban-fallback'?'<div class="empty"><strong>District urban proxy</strong>Local values use the district urban population where constituency coverage was unavailable.</div>':''}${Object.keys(india).map(k=>`<div class="demo-row"><div><span>${title(k)}</span><strong>${d.religions[k].toFixed(1)}%</strong></div><div class="demo-track"><i style="width:${d.religions[k]}%"></i></div><div class="demo-track national"><i style="width:${india[k]}%"></i></div><small class="small">India ${india[k].toFixed(1)}%</small></div>`).join('')}<p class="small">Other religions and unreported responses account for the remainder.</p><div class="empty"><strong>Age · gender · caste</strong>No verified resident breakdown matched to this constituency is loaded. Registered voters and all residents are different populations.</div><a class="small" href="https://www.pib.gov.in/newsite/printrelease.aspx?lang=2&amp;reg=3&amp;relid=126326" target="_blank" rel="noopener">Official national Census benchmark ↗</a>`}
function localView(s){const n=current.code==='KL'&&current.year===2026?DATA.kerala.national[s.id]:null;return `<h3 class="mini-heading">INSIDE ${esc(s.name.toUpperCase())}</h3>${current.map[s.id]?`<svg id="seat-shape" class="seat-map" viewBox="${bounds([current.map[s.id]])}" aria-label="Outline of ${esc(s.name)}"><path d="${current.map[s.id]}" fill="${color(keyFor(s.winner))}"/></svg>`:'<p class="note">Verified polygon not loaded for this seat.</p>'}<div class="empty"><strong>Subdivision voting map</strong>Verified booth / ward geometry is not joined to election results in this edition. A constituency winner is not assigned to every subdivision.</div>${n?`<h3 class="mini-heading">2024 NATIONAL · ${n.booths.length} POLLING STATIONS</h3><p class="small">EVM only. Booth IDs are polling stations, not geographic polygons.</p><div class="table-wrap" style="max-height:270px;overflow:auto"><table><thead><tr><th>Booth</th><th>UDF</th><th>LDF</th><th>NDA</th></tr></thead><tbody>${n.booths.map(b=>`<tr><td>${b.booth}</td><td>${fmt(b.UDF)}</td><td>${fmt(b.LDF)}</td><td>${fmt(b.NDA)}</td></tr>`).join('')}</tbody></table></div><a class="small" href="${esc(n.source)}" target="_blank" rel="noopener">Official booth sheet ↗</a>`:''}<h3 class="mini-heading">${esc(s.region.toUpperCase())} · ${esc(current.regionKind.toUpperCase())}</h3><div class="region-seats">${Object.values(current.seats).filter(a=>a.region===s.region).map(a=>`<button class="quiet" data-seat="${a.id}">${esc(title(a.name))} <span style="color:${color(keyFor(a.winner))}">●</span></button>`).join('')}</div>`}
function renderClose(){const close=Object.values(current.seats).filter(s=>s.margin!==null).sort((a,b)=>a.margin-b.margin).slice(0,4);$('#close-cards').innerHTML=close.map(s=>`<button class="close-card" data-seat="${s.id}"><small>${esc(s.region)} / ${current.code==='LS'?'PC':'AC'} ${s.id}</small><h3>${esc(title(s.name))} ↗</h3><div>${chip(keyFor(s.winner))} <span class="small">won</span></div><div class="margin">${fmt(s.margin)} <small>votes</small></div><div class="label">${(s.marginPct??0).toFixed(2)} pp · vs ${esc(s.runner.party)}</div></button>`).join('')}
function filtered(){const q=$('#search').value.toLowerCase().trim(),region=$('#region').value,p=$('#party-filter').value;const list=seats().filter(s=>(!$('#flips-only').checked||flipInfo(s).flipped)&&(!p||keyFor(s.winner)===p)&&(!region||(current?s.region===region:s.state===region))&&(!q||[s.name,s.region,getState(s.state).name,...s.candidates.map(c=>c.name)].some(v=>v.toLowerCase().includes(q))));const order=$('#sort').value;list.sort((a,b)=>order==='close'?(a.margin??Infinity)-(b.margin??Infinity):order==='wide'?(b.margin??-Infinity)-(a.margin??-Infinity):order==='share'?(b.totalVotes?b.winner.votes/b.totalVotes:-1)-(a.totalVotes?a.winner.votes/a.totalVotes:-1):getState(a.state).name.localeCompare(getState(b.state).name)||Number(a.id)-Number(b.id));return list}
function showTip(tip,event,host,content){const box=host.getBoundingClientRect();tip.innerHTML=content;tip.style.display='block';tip.style.left=Math.max(8,Math.min(event.clientX-box.left+12,box.width-240))+'px';tip.style.top=Math.max(8,Math.min(event.clientY-box.top+12,box.height-95))+'px'}
document.addEventListener('click',event=>{const state=event.target.closest('[data-state]');if(state){selectState(state.dataset.state);return}const open=event.target.closest('[data-open-state]');if(open){if(current?.code===open.dataset.openState)chooseSeat(open.dataset.openSeat,true);else{selectState(open.dataset.openState,open.dataset.openSeat,false);$('#detail').scrollIntoView({behavior:'smooth',block:'start'})}return}const seat=event.target.closest('[data-seat]');if(seat){chooseSeat(seat.dataset.seat,!seat.closest('#map'));return}const tab=event.target.closest('[data-tab]');if(tab){detailTab=tab.dataset.tab;renderDetail();return}const mode=event.target.closest('[data-mode]');if(mode){mapMode=mode.dataset.mode;renderMap();return}const group=event.target.closest('[data-group]');if(group){grouping=group.dataset.group;renderState();configureYearPicker();return}});
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const node=e.target;if(node.matches('svg [data-state]')){e.preventDefault();selectState(node.dataset.state)}else if(node.matches('svg [data-seat]')){e.preventDefault();chooseSeat(node.dataset.seat)}});
$('#india-map').addEventListener('pointermove',e=>{const code=e.target.dataset.state;if(!code)return;const s=getState(code);showTip($('#country-tip'),e,$('.country-map-wrap'),`<strong>${esc(s.name)} · ${s.year}</strong><br>${chip(s.largest)} ${s.counts[s.largest]} of ${s.total} seats<br><small>Click to explore this election →</small>`)});$('#india-map').addEventListener('pointerleave',()=>$('#country-tip').style.display='none');
$('#map').addEventListener('pointermove',e=>{if(!e.target.dataset.seat)return;const s=current.seats[e.target.dataset.seat];showTip($('#tooltip'),e,$('.map-wrap'),`<strong>${esc(title(s.name))}</strong><br>${chip(keyFor(s.winner))} ${esc(title(s.winner.name))}<br><small>${mapMode==='shift'?signed(delta(s,$('#shift-party').value)):s.margin===null?'Margin unavailable':fmt(s.margin)+' vote margin'}</small>`)});$('#map').addEventListener('pointerleave',()=>$('#tooltip').style.display='none');
for(const id of ['back'])$('#'+id).addEventListener('click',e=>{e.preventDefault();selectState('IN');document.title='India Votes'});
$('#state-picker').addEventListener('change',()=>selectState($('#state-picker').value));$('#state-search').addEventListener('input',renderStateList);$('#search').addEventListener('input',()=>{pageSize=60;renderTable()});$('#party-filter').addEventListener('change',()=>{pageSize=60;renderTable()});$('#sort').addEventListener('change',()=>{pageSize=60;renderTable()});$('#region').addEventListener('change',()=>{if(current){$('#map-region').value=$('#region').value;renderMap()}pageSize=60;renderTable()});$('#map-region').addEventListener('change',()=>{$('#region').value=$('#map-region').value;renderMap();renderTable()});$('#baseline').addEventListener('change',()=>renderMap());$('#shift-party').addEventListener('change',()=>renderMap());$('#reset').addEventListener('click',()=>{mapMode='winner';$('#map-region').value='';$('#region').value='';renderMap();renderTable()});$('#load-more').addEventListener('click',()=>{pageSize+=100;renderTable()});$('#show-close').addEventListener('click',()=>{$('#sort').value='close';$('#region').value='';$('#map-region').value='';$('#party-filter').value='';$('#search').value='';renderMap();renderTable()});
$('#download').addEventListener('click',()=>{const rows=[['State','Election year','Constituency number','Constituency','Region type','Region','Winner','Party','Winner votes','Runner-up','Runner-up party','Runner-up votes','Margin votes','Total votes including NOTA','Status'],...filtered().map(s=>[getState(s.state).name,s.year,s.id,s.name,getState(s.state).regionKind,s.region,s.winner.name,s.winner.party,s.unopposed?'':s.winner.votes,s.runner?.name||'',s.runner?.party||'',s.runner?.votes??'',s.margin??'',s.totalVotes??'',s.unopposed?'Unopposed':s.partialCandidates?'Winner only':'Declared'])];const csv=rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');downloadFile(`${current?current.code+'-'+current.year:'india'}-assembly-results.csv`,csv,'text/csv;charset=utf-8')});$('#export-data').addEventListener('click',()=>{const clone=JSON.parse($('#atlas-data').textContent);downloadFile('india-assembly-atlas-data.json',JSON.stringify(clone))});


// India Votes: election-specific coalitions and multi-cycle browsing.
function hydrate(state){if(!state)return;if(state.mapRef&&Object.keys(state.map).length===0)state.map=latestStates.find(s=>s.code===state.mapRef).map;if(state.mapReuseYear){const previous=DATA.national[String(state.mapReuseYear)].map;state.map=Object.fromEntries(Object.keys(state.seats).filter(k=>state.map[k]||previous[k]).map(k=>[k,state.map[k]||previous[k]]));delete state.mapReuseYear}state.chamber=state.chamber||(state.code==='LS'?'national':'assembly');for(const seat of Object.values(state.seats)){seat.state=state.code;seat.year=state.year;seat.totalVotes=seat.partialCandidates?null:seat.candidates.reduce((n,c)=>n+c.votes,0);seat.winner=seat.candidates.find(c=>c.party!=='NOTA');seat.runner=seat.candidates.filter(c=>c.party!=='NOTA')[1]||null;seat.unopposed=!seat.runner&&seat.winner.votes===0;seat.margin=seat.runner?seat.winner.votes-seat.runner.votes:null;seat.marginPct=seat.margin!==null&&seat.totalVotes?seat.margin/seat.totalVotes*100:null}}
function versionFor(code,year){if(code==='LS')return DATA.national[String(year)];const v=DATA.elections[code]?.[String(year)];return v?.latestRef?latestStates.find(s=>s.code===code):v}
function configureYearPicker(){const versions=current?(current.code==='LS'?DATA.national:DATA.elections[current.code]):null;$('#year-picker-label').hidden=!versions;if(!versions)return;$('#election-year').innerHTML=Object.keys(versions).sort((a,b)=>Number(b)-Number(a)).map(y=>`<option value="${y}">${y}</option>`).join('');$('#election-year').value=String(current.year)}
function selectState(code,id=null,scroll=true){hideResearch();const s=getState(code);hydrate(s);$('#party-guide').hidden=true;$('#races').hidden=false;$('#flips-only').checked=false;selectStateBase(code,id,scroll);chamber=s?.code==='LS'?'national':'assembly';$('#state-picker-label').hidden=chamber==='national';$('#national-nav').classList.toggle('active',chamber==='national');$('#state-nav').classList.toggle('active',chamber==='assembly');$('#guide-nav').classList.remove('active');configureYearPicker();$('#races-title').textContent=`Constituency results · ${current?current.name+' · '+current.year:'latest state elections'}`;if(current)history.replaceState(null,'',`#chamber=${chamber}&state=${current.code}&year=${current.year}&seat=${selected}`)}
function flipInfo(s){const state=current&&s.state===current.code?current:latestStates.find(x=>x.code===s.state);const old=state?.previous[s.id];const prev=s.previousMatched&&old?old.candidates.find(c=>c.party!=='NOTA'):null;const lineage=k=>k==='Congress-led UPA'||k==='Maha Vikas Aghadi'||k==='Congress–NCP'?'INDIA':k==='Mahayuti'||k==='BJP–Shiv Sena'||k.includes('NDA')?'NDA':k;return{prev,flipped:!!prev&&prev.party!==s.winner.party&&(grouping==='party'||lineage(keyFor(prev))!==lineage(keyFor(s.winner))),from:prev?keyFor(prev):null,to:keyFor(s.winner)}}
function labelFor(p){return p==='IND'?'Independent':p==='OTHER'?'Other / unaligned':groupLabel(p)}
function completePriorCounts(){if(current?.code==='LS'&&current.year===2024&&DATA.national['2019']._seatTallies)return DATA.national['2019']._seatTallies[grouping==='alliance'?'alliance':'party'];if(current?.code==='LS'&&current.year===2024){const out={};for(const seat of Object.values(DATA.national['2019'].seats)){const w=seat.candidates.find(c=>c.party!=='NOTA'),k=keyFor(w);out[k]=(out[k]||0)+1}return out}if(!current?.previousComparable||Object.keys(current.previous).length!==current.total)return null;const out={};for(const p of Object.values(current.previous)){const w=p.candidates.find(c=>c.party!=='NOTA');if(w){const k=keyFor(w);out[k]=(out[k]||0)+1}}return out}
function setPartyFilter(){const ps=[...new Set(seats().map(s=>keyFor(s.winner)))].sort();$('#party-filter').innerHTML='<option value="">All winning groups</option>'+ps.map(p=>`<option value="${esc(p)}">${esc(labelFor(p))}</option>`).join('')}
function renderState(){const isNational=current.code==='LS',count=Object.keys(current.seats).length;document.title=`India Votes · ${isNational?'Lok Sabha':current.name} ${current.year}`;$('#state-title').textContent=isNational?'Lok Sabha election results':`${current.name} election results`;$('#state-subtitle').textContent=`${current.year} ${isNational?'Lok Sabha · Lower house of Parliament':'State legislative assembly'} · ${current.total} elected seats · the candidate with the most votes wins the seat.`;$('#state-date').innerHTML=`<span class="dot"></span> HISTORICAL RESULT<br><small>${current.year} election · ${Math.floor(current.total/2)+1} seats for a majority</small>`;$('#grouping').hidden=false;$$('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group===grouping));$('#state-coverage').textContent=`${count}/${current.total} seat outcomes · ${Object.keys(current.map).length} polygons · ${Object.values(current.seats).filter(s=>s.previousMatched).length} comparable seats`;const regions=[...new Set(Object.values(current.seats).map(s=>s.region))].sort(),opts=`<option value="">All ${isNational?'states / UTs':current.regionKind.toLowerCase()+'s'}</option>`+regions.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');$('#region').innerHTML=opts;$('#map-region').innerHTML=opts;$('#map-region').setAttribute('aria-label',isNational?'Map state or territory':`Map ${current.regionKind.toLowerCase()}`);$('#baseline').innerHTML=current.previousYear?`<option value="${current.previousYear}">${current.previousYear} ${isNational?'national':'assembly'}</option>`:'<option value="">No comparable baseline</option>';if(current.code==='KL'&&current.year===2026&&grouping==='alliance')$('#baseline').insertAdjacentHTML('beforeend','<option value="2024">2024 national · 7 segments</option>');setPartyFilter();renderTotals();renderMap();renderDetail();renderClose();renderTable();configureYearPicker()}
function renderTotals(){const counts=statCounts(current,grouping==='alliance'),prior=completePriorCounts(),all=Object.values(current.seats),hasPartial=all.some(s=>s.partialCandidates),total=all.filter(s=>!s.partialCandidates).reduce((n,s)=>n+s.totalVotes,0),votes={};for(const s of all){if(s.partialCandidates)continue;for(const c of s.candidates){const k=keyFor(c);votes[k]=(votes[k]||0)+c.votes}}for(const p of Object.keys(votes))if(p!=='NOTA'&&!counts.some(x=>x[0]===p))counts.push([p,0]);counts.sort((a,b)=>b[1]-a[1]||(votes[b[0]]||0)-(votes[a[0]]||0));const groups=Object.entries(current.coalitionMembers||{});$('#coalition-explainer').innerHTML=grouping==='alliance'?`<strong>Coalition view · ${current.year}</strong> ${current.coalitionReviewed?'Grouped by the alliance in this election.':'No reviewed joint-ticket map here: parties remain separate.'} <details><summary>Who is included?</summary>${current.code==='KL'?'<p>UDF, LDF and NDA use reviewed candidate-level historical tags, including supported independents.</p>':groups.length?groups.map(([k,ps])=>`<p>${chip(k)} ${ps.map(p=>esc(p)).join(' · ')}</p>`).join(''):'<p>None grouped. This does not assign parties to today’s national alliances.</p>'}<p>${esc(current.coalitionNote||'Membership is specific to the election shown.')}</p></details>`:'<strong>Party view.</strong> Each party is counted separately. Switch to Coalitions to see reviewed electoral partners together.';
 $('#totals').innerHTML=counts.slice(0,6).map(([p,n])=>{const knownBefore=Object.values(current.previous||{}).some(s=>s.candidates.some(c=>keyFor(c)===p));const d=prior&&(p in prior||knownBefore)?n-(prior[p]||0):null;return `<div class="total" style="--accent:${color(p)}"><div class="top"><strong>${esc(labelFor(p))}</strong><small>${n>=Math.floor(current.total/2)+1?'MAJORITY':''}</small></div><div class="score">${n}<span>seats</span></div><div class="seat-change">${d===null?(prior?'Different / new grouping':'No complete previous tally'):`${d>=0?'+':''}${d} seats vs ${current.previousYear}`}</div><div class="foot"><span>${hasPartial?'Vote-share record incomplete':`${((votes[p]||0)/total*100).toFixed(1)}% vote share`}</span></div></div>`}).join('');$('#assembly-label').textContent=`${current.total} ELECTED ${current.code==='LS'?'NATIONAL PARLIAMENT':'STATE ASSEMBLY'} SEATS`;$('#majority-label').textContent=`${Math.floor(current.total/2)+1} for a majority`;$('#seatbar').innerHTML=counts.map(([p,n])=>`<div style="width:${n/current.total*100}%;background:${color(p)}" title="${esc(labelFor(p))}: ${n} seats"></div>`).join('');$('#blocks').innerHTML=[...all].sort((a,b)=>counts.findIndex(x=>x[0]===keyFor(a.winner))-counts.findIndex(x=>x[0]===keyFor(b.winner))).map(s=>{const f=flipInfo(s);return `<button data-seat="${s.id}" class="${f.flipped?'flipped-block':''}" style="background:${color(keyFor(s.winner))}" title="${esc(s.name)} · ${esc(labelFor(keyFor(s.winner)))}${f.flipped?' · flipped from '+f.from:''}" aria-label="Explore ${esc(s.name)}${f.flipped?', flipped seat':''}"></button>`}).join('');const prev=$('#shift-party').value;$('#shift-party').innerHTML=counts.map(([p])=>`<option value="${esc(p)}">${esc(labelFor(p))}</option>`).join('');if(counts.some(x=>x[0]===prev))$('#shift-party').value=prev}
function polygonCenter(p){const ns=p.match(/-?\d+(?:\.\d+)?/g).map(Number);let x=0,y=0,n=0;for(let i=0;i<ns.length;i+=2){x+=ns[i];y+=ns[i+1];n++}return [x/n,y/n]}
function renderMap(){const region=$('#map-region').value,all=Object.values(current.seats),mapped=Object.keys(current.map).length>=current.total*.8;$('#map').hidden=!mapped;$('#map-tiles').hidden=mapped;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mapMode));$('#baseline').hidden=!['shift','flips'].includes(mapMode);$('#shift-party').hidden=mapMode!=='shift';const target=$('#shift-party').value;$('#map-title').textContent=mapMode==='shift'?`Vote-share change · ${labelFor(target)}`:mapMode==='flips'?'Seats that changed hands':mapMode==='margin'?'How close was each race?':'Who won each seat';$('#map-caption').textContent=mapMode==='shift'?`→ share increased · ← share decreased · compared with ${$('#baseline').value||'unavailable'} · longer arrows = bigger change`:mapMode==='flips'?`Coloured seats changed ${grouping==='alliance'?'coalition':'party'}; grey = held or no comparable record.`:mapMode==='margin'?'Lead over runner-up: under 2 points is close; 2–10 competitive; over 10 a wider win.':'Select a seat to see results and historical changes together.';
 const visible=all.filter(s=>!region||s.region===region);const vb=bounds(visible.filter(s=>current.map[s.id]).map(s=>current.map[s.id])),width=Number(vb.split(' ')[2])||1;
 if(mapped){let markup=all.filter(s=>current.map[s.id]).map(s=>{const f=flipInfo(s);let fill=mapMode==='shift'?swingFill(s,target):mapMode==='flips'?(f.flipped?color(keyFor(s.winner)):'#374236'):mapMode==='margin'?strengthColor(color(keyFor(s.winner)),s.marginPct,30):color(keyFor(s.winner));return `<path d="${current.map[s.id]}" fill="${fill}" data-seat="${s.id}" class="${region&&s.region!==region?'dim ':''}${s.id===selected?'selected':''}" tabindex="0" role="button" aria-label="${esc(s.name)}, ${esc(labelFor(keyFor(s.winner)))}${f.flipped?', flipped from '+esc(f.from):''}"><title>${esc(s.name)} · ${esc(labelFor(keyFor(s.winner)))} ${s.marginPct===null?'':`+${s.marginPct.toFixed(1)} points`}${f.flipped?' · FLIPPED':''}</title></path>`}).join('');if(mapMode==='shift'){const arrows=visible.map(s=>({s,v:delta(s,target)})).filter(x=>x.v!==null).sort((a,b)=>Math.abs(b.v)-Math.abs(a.v)).slice(0,100);markup+=arrows.map(({s,v})=>{const [x,y]=polygonCenter(current.map[s.id]||'M0,0L0,0Z');const size=(Number(vb.split(' ')[3])||width)/620*(12+10*Math.min(Math.abs(v)/15,1));return `<text x="${x}" y="${y}" class="swing-arrow" text-anchor="middle" dominant-baseline="middle" font-size="${size}" fill="${arrowInk()}">${v>=0?'→':'←'}</text>`}).join('')}$('#map').innerHTML=markup;$('#map').setAttribute('viewBox',vb)}else{$('#map').innerHTML='';$('#map-tiles').innerHTML=visible.map(s=>`<button data-seat="${s.id}" style="--accent:${mapMode==='shift'?swingFill(s,target):mapMode==='margin'?strengthColor(color(keyFor(s.winner)),s.marginPct,30):mapMode==='flips'&&!flipInfo(s).flipped?'#71806a':color(keyFor(s.winner))}" title="${esc(s.name)}">${s.id}${mapMode==='shift'?`<small>${delta(s,target)===null?'—':(delta(s,target)>=0?'→ +':'← −')+Math.abs(delta(s,target)).toFixed(1)}</small>`:''}</button>`).join('')}
 $('#map-legend').innerHTML=mapMode==='shift'?`${chip(target)} → gained · ← lost · vivid shades = larger change · arrows label up to 100 largest changes`:mapMode==='margin'?'Party colour = winner · darker vivid shade = smaller lead · brighter shade = wider lead · grey = unavailable':mapMode==='flips'?`${all.filter(s=>flipInfo(s).flipped).length} comparable seats changed hands · outlined blocks mark flips`:statCounts(current,grouping==='alliance').slice(0,5).map(([p])=>`<span style="color:${color(p)}">● ${esc(labelFor(p))}</span>`).join(' &nbsp; ');$('#map-note').textContent=(!mapped?`Constituency grid: verified geographic outlines cover ${Object.keys(current.map).length}/${current.total} seats. Every result remains selectable below. `:'')+current.mapNote+(current.code==='GJ'?' Karanj AC 160 has no polygon; its result remains searchable.':'')}
function candidateDelta(s,c){if(!s.previousMatched||s.partialCandidates)return null;const old=shares(prevSeat(s).candidates),now=shares(s.candidates);if(grouping==='alliance'&&keyFor(c)==='INDIA'&&!('INDIA' in (old||{})))return null;return old&&now?(now[keyFor(c)]||0)-(old[keyFor(c)]||0):null}
function candidateRows(s){return s.candidates.map((c,i)=>{const d=i<3?candidateDelta(s,c):null;return `<div class="candidate" style="--accent:${color(keyFor(c))}"><div class="candidate-main"><div class="avatar" title="Candidate initials">${esc(c.name.split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</div><div><strong>${esc(title(c.name))}${c===s.winner?' ✓':''}</strong><small>${chip(c.party)}${grouping==='alliance'&&keyFor(c)!==c.party?' '+esc(labelFor(keyFor(c))):''}</small><button class="text-link" data-review-name="${esc(c.name)}" data-review-state="${current.code}" data-review-year="${current.year}">Profile & background ↗</button>${d===null?'':`<div class="inline-shift">${d>=0?'↗':'↙'} ${signed(d)} vs ${current.previousYear}<small> ${esc(labelFor(keyFor(c)))} share</small></div>`}</div><div class="votes">${s.unopposed?'Unopposed':fmt(c.votes)}<small>${s.totalVotes?`${(c.votes/s.totalVotes*100).toFixed(1)}%`:'Share unavailable'}</small></div></div>${s.totalVotes?`<div class="track"><i style="width:${c.votes/s.totalVotes*100}%"></i></div>`:''}</div>`}).join('')}
function marginCompare(s){const old=s.previousMatched?prevSeat(s):null,ranked=old?[...old.candidates].filter(c=>c.party!=='NOTA').sort((a,b)=>b.votes-a.votes):[],total=old?.candidates.reduce((n,c)=>n+c.votes,0)||0,pm=ranked.length>1&&total?(ranked[0].votes-ranked[1].votes)/total*100:null;return `<div class="margin-compare"><div class="margin-result previous"><small>${current.previousYear||'Previous'} election</small><strong>${pm===null?'Unavailable':`${esc(labelFor(keyFor(ranked[0])))} +${pm.toFixed(1)}`}</strong><span>winning lead · points</span></div><span class="comparison-arrow">→</span><div class="margin-result"><small>${current.year} election</small><strong style="color:${color(keyFor(s.winner))}">${s.marginPct===null?(s.unopposed?'Unopposed':'Incomplete'):esc(labelFor(keyFor(s.winner)))+' +'+s.marginPct.toFixed(1)}</strong><span>${s.margin===null?'':fmt(s.margin)+' votes ahead'}</span></div></div>`}
function renderDetail(){const s=current.seats[selected],f=flipInfo(s);$('#detail').innerHTML=`<div class="eyebrow">${esc(s.region.toUpperCase())} / ${current.code==='LS'?'PARLIAMENTARY':'ASSEMBLY'} SEAT</div><div class="subhead"><h2>${esc(title(s.name))}</h2><span class="badge ${f.flipped?'flip-badge':''}">${s.unopposed?'UNOPPOSED':f.flipped?'↻ FLIPPED':'DECLARED'}</span></div>${f.flipped?`<p class="flip-story">${chip(f.from)} → ${chip(f.to)} <span>changed hands since ${current.previousYear}</span></p>`:''}${marginCompare(s)}<p class="margin-explanation">The winning lead is the difference between the top two candidates’ vote shares. One percentage point means one additional vote in every 100 cast.</p>${s.note?`<p class="note">${esc(s.note)}</p>`:''}<div class="detail-tabs" role="tablist">${[['results','Results & changes'],['local','Local detail'],['people','People']].map(([t,l])=>`<button role="tab" data-tab="${t}" aria-selected="${detailTab===t}" class="${detailTab===t?'active':''}">${l}</button>`).join('')}</div><div id="detail-content">${detailTab==='results'?`<p class="small">CANDIDATES <span style="float:right">VOTES / SHARE</span></p>${candidateRows(s)}<div class="probability-note"><strong>Won · Final result</strong><span>Votes counted and result declared. This is a historical result, not a forecast.</span></div><a class="small" href="${esc(s.source)}" target="_blank" rel="noopener">View result source ↗</a><div class="integrated-history">${pastView(s)}</div>`:detailTab==='people'?peopleView(s):localView(s)}</div>`}
function renderTable(){const list=filtered();$('#race-count').textContent=`${fmt(list.length)} matching seats · Showing ${Math.min(pageSize,list.length)} · ${grouping==='alliance'?'Coalition':'Party'} changes where comparable`;$('#race-rows').innerHTML=list.slice(0,pageSize).map(s=>{const f=flipInfo(s);return `<tr><td><button class="row-action" data-open-state="${s.state}" data-open-seat="${s.id}">${esc(title(s.name))} ↗</button><small>${esc(getState(s.state).name)} · ${s.year} · ${esc(s.region)}</small></td><td>${chip(keyFor(s.winner))} ${esc(title(s.winner.name))}${f.flipped?`<small class="flip-label">↻ Flipped from ${esc(f.from)}</small>`:''}</td><td>${s.runner?`${chip(keyFor(s.runner))} ${esc(title(s.runner.name))}<small>${fmt(s.runner.votes)} votes</small>`:s.unopposed?'Unopposed':''}</td><td>${s.unopposed?'—':fmt(s.winner.votes)}<small>${s.totalVotes?shareText(s)+' of votes':''}</small></td><td><strong style="color:${color(keyFor(s.winner))}">${s.marginPct===null?'—':esc(labelFor(keyFor(s.winner)))+' +'+s.marginPct.toFixed(1)}</strong><small>${s.margin===null?'':fmt(s.margin)+' votes ahead'}</small></td><td><span class="badge ${f.flipped?'flip-badge':''}">${s.unopposed?'UNOPPOSED':s.partialCandidates?'PARTIAL RECORD':f.flipped?'FLIPPED':'DECLARED'}</span></td></tr>`}).join('')||'<tr><td colspan="6">No matching races.</td></tr>';$('#load-more').hidden=pageSize>=list.length}
function renderGuideLegacy(){const lanes=['Left / socialist','Centre / broad tent','Right / nationalist','Regional / cross-cutting'];$('#guide-lanes').innerHTML=lanes.map(lane=>`<section class="guide-lane"><h2>${lane}</h2>${DATA.guide.filter(p=>p.lane===lane).map(p=>`<article class="party-card" style="--accent:${color(p.party)}">${chip(p.party)}<h3>${esc(p.name)}</h3><span class="orientation">${esc(p.orientation)}</span><dl><dt>Prominent leader / face</dt><dd>${esc(p.leader)}<small>${esc(p.era)}</small></dd><dt>Main electoral emphasis</dt><dd>${esc(p.aim)}</dd></dl><p>${esc(p.context)}</p><div class="guide-sources">${p.sources.map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`).join('')}</div></article>`).join('')}</section>`).join('')}
$('#election-year').addEventListener('change',async()=>{const year=$('#election-year').value,code=current?.code||contextCode,oldGroup=grouping;if(code==='LS')nationalYear=year;else activeVersions[code]=versionFor(code,year);await selectState(code,null,false);grouping=oldGroup;renderState();history.replaceState(null,'',`#chamber=${chamber}&state=${code}&year=${year}&seat=${selected}`)});
