const EDU_ORDER=['Illiterate','Literate','5th Pass','8th Pass','10th Pass','12th Pass','Graduate','Graduate Professional','Post Graduate','Doctorate'];
function eduLevel(e){return e==='Graduate Professional'?'Graduate':e}
