function setupGeography(select,all=false){select.innerHTML=(all?'<option value="ALL">Master list · latest and loaded elections</option>':'')+'<option value="LS">National · Lok Sabha</option>'+latestStates.map(s=>`<option value="${s.code}">${esc(s.name)}</option>`).join('')}
