function directorySnapshots(){const c=$('#directory-state').value,y=$('#directory-year').value;if(c==='ALL')return [...latestStates,...Object.values(DATA.national),...Object.entries(DATA.elections).flatMap(([code,vs])=>Object.entries(vs).filter(([,v])=>!v.latestRef).map(([,v])=>v))];return y==='ALL'?Object.keys(versionsFor(c)).map(y=>versionFor(c,y)):[versionFor(c,y)]}
function partyProfile(p){const n=nameKey(DATA.partyNames[p]||p);return DATA.guide.find(g=>g.party===p||nameKey(g.name)===n)}
function renderGuide(){if(!$('#directory-state').options.length){setupGeography($('#directory-state'),true);$('#directory-state').value=current&&current.code!=='LS'?current.code:'ALL';directoryYears()}const snapshots=directorySnapshots().filter(s=>s&&Object.keys(s.seats||{}).length),parties=new Map();for(const s of snapshots)for(const seat of Object.values(s.seats))for(const c of seat.candidates){if(c.party==='NOTA')continue;const p=parties.get(c.party)||{candidates:0,coalitions:new Set(),places:new Set()};p.candidates++;p.coalitions.add(c.coalition||c.alliance||c.party);p.places.add(s.code==='LS'?'Lok Sabha':s.name);parties.set(c.party,p)}const q=$('#directory-search').value.toLowerCase();const list=[...parties].filter(([p])=>[p,DATA.partyNames[p],partyProfile(p)?.name].join(' ').toLowerCase().includes(q)).sort((a,b)=>Number(!!partyProfile(b[0]))-Number(!!partyProfile(a[0]))||a[0].localeCompare(b[0]));$('#directory-count').textContent=`${list.length} party labels · ${snapshots.length} election snapshots · labels follow the source archive; historical renamings and factions may appear separately. Independent is a candidate category, not a party.`;$('#guide-lanes').innerHTML=list.map(([p,m])=>{const g=partyProfile(p);return `<article class="party-card directory-card" style="--accent:${color(p)}">${chip(p)} <span class="record-tag">${p==='IND'||p.startsWith('Independent')?'Candidate category':g?'Researched introduction':'Source label · profile pending'}</span><h2>${esc(g?.name||DATA.partyNames[p]||p)}</h2>${g?`<div class="orientation">${esc(g.orientation)}</div><dl><dt>Prominent electoral face</dt><dd>${esc(g.leader)}<small>${esc(g.era)}</small></dd><dt>Electoral emphasis</dt><dd>${esc(g.aim)}</dd></dl><p>${esc(g.context)}</p>`:'<p>A candidate label in the selected election archive. Leader biography and policy summary have not yet been reviewed.</p>'}<div class="party-membership"><small>In these selected elections</small><p>${[...m.coalitions].slice(0,9).map(esc).join(' · ')}</p><small>${m.candidates.toLocaleString()} candidate entries across ${m.places.size} election geographies</small></div><div class="guide-sources">${g?g.sources.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(l)} ↗</a>`).join(''):'<a href="https://www.eci.gov.in/statistical-reports" target="_blank" rel="noopener">ECI statistical reports ↗</a>'}</div></article>`}).join('')||'<p>No parties match this search.</p>'}
function bioFor(r){return DATA.candidateReview.bios.find(b=>b.state===r.state&&b.party===r.party&&nameKey(b.name)===nameKey(r.name))}
function candidateYears(){const c=$('#candidate-state').value;$('#candidate-year').innerHTML=Object.keys(versionsFor(c)).sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('');if(Object.keys(versionsFor(c)).includes(contextYear))$('#candidate-year').value=contextYear;loadCandidateElection()}
function loadCandidateElection(){labState=versionFor($('#candidate-state').value,$('#candidate-year').value);hydrate(labState);const isImported=labState.code==='KL'&&labState.year===2021;if(isImported){labRows=DATA.candidateReview.records.map(r=>({...r,bio:bioFor(r)}))}else{labRows=Object.values(labState.seats).flatMap(s=>s.candidates.filter(c=>c.party!=='NOTA').map((c,i)=>{const r={uid:s.id+'-'+i,name:c.name,seat:s.name,seatId:s.id,party:c.party,resultName:c.name,state:labState.code,year:labState.year};r.bio=bioFor(r);if(r.bio?.education)r.education=r.bio.education;return r}))}$('#candidate-party').innerHTML='<option value="">All parties</option>'+[...new Set(labRows.map(r=>r.party))].sort().map(p=>`<option value="${esc(p)}">${esc(DATA.partyNames[p]||p)}</option>`).join('');$('#candidate-search').value='';$('#candidate-coverage').value='all';labLimit=40;labSelected=null;renderCandidates()}
function filteredLab(){const q=$('#candidate-search').value.toLowerCase(),party=$('#candidate-party').value,cov=$('#candidate-coverage').value;return labRows.filter(r=>(!party||r.party===party)&&(!q||[r.name,r.seat,r.bio?.institution,r.education].join(' ').toLowerCase().includes(q))&&(cov==='all'||(cov==='known')===!!r.source))}
function statCard(label,value,note){return `<article><small>${esc(label)}</small><strong>${esc(value)}</strong><p>${esc(note)}</p></article>`}
function renderCandidates(){const rs=filteredLab();if(!rs.some(r=>r.uid===labSelected))labSelected=(rs.find(r=>r.bio)||rs[0])?.uid;const known=rs.filter(r=>r.education&&EDU_RANK[eduLevel(r.education)]!==undefined),ranked=known.map(r=>eduLevel(r.education)).sort((a,b)=>EDU_RANK[a]-EDU_RANK[b]);const freq={};for(const e of ranked)freq[e]=(freq[e]||0)+1;const max=ranked.at(-1)||'Unknown',mid=ranked.length?ranked.length%2?ranked[(ranked.length-1)/2]:ranked[ranked.length/2-1]===ranked[ranked.length/2]?ranked[ranked.length/2]:ranked[ranked.length/2-1]+' / '+ranked[ranked.length/2]:'Unknown';const modes=Object.entries(freq).filter(([,n])=>n===Math.max(0,...Object.values(freq))).map(([e])=>e).join(' / ')||'Unknown';const cases=rs.filter(r=>Number.isInteger(r.cases)),gender=rs.filter(r=>r.gender);$('#candidate-summary').innerHTML=statCard('Roster in this view',rs.length,labState.code==='KL'&&labState.year===2021?'ADR analysed subset; not every ballot candidate':'Election result candidates · background coverage varies')+statCard('Education coverage',known.length+'/'+rs.length,`${rs.length-known.length} unknown or unclassified`)+statCard('Median / most common',mid,`Mode: ${modes}. Highest: ${max}.`)+statCard('Declared cases',cases.filter(r=>r.cases>0).length+'/'+cases.length,`${rs.length-cases.length} unknown · cases are not convictions`)+statCard('Recorded women',rs.filter(r=>r.gender==='Female').length+'/'+rs.length,`${gender.length}/${rs.length} gender coverage; others unclassified`)+statCard('Religion / caste','Not collected','No identity inference; no diversity percentage');
 const distribution=Object.entries(freq).sort((a,b)=>EDU_RANK[a[0]]-EDU_RANK[b[0]]).map(([e,n])=>`<span style="--accent:${eduColors[e]}">${esc(e)} <b>${n}</b></span>`).join('');$('#candidate-map-title').textContent=`${labState.name} · ${labState.year} · ${$('#candidate-measure').selectedOptions[0].text}`;$('#candidate-count').innerHTML=`${rs.length} matching roster entries · ${Math.min(labLimit,rs.length)} shown. ${labState.code==='KL'&&labState.year===2021?`${DATA.candidateReview.coverage.affidavitSummaries}/957 affidavit rows linked to result candidates; ${957-DATA.candidateReview.coverage.affidavitSummaries} are kept as unlinked profiles.`:''}<div class="education-distribution">${distribution}</div>`;
 renderCandidateMap(rs);renderCandidateProfile(rs.find(r=>r.uid===labSelected));$('#candidate-roster').innerHTML=rs.slice(0,labLimit).map(r=>`<button class="roster-card ${r.uid===labSelected?'active':''}" data-profile="${esc(r.uid)}"><div>${chip(r.party)} <span class="record-tag">${r.source?'Affidavit · '+r.year:r.bio?'Sourced biography':'Background not imported'}</span></div><h3>${esc(title(r.name))}</h3><p>${esc(title(r.seat))}</p><small>${esc(r.education||'Education unknown')} · ${r.cases===undefined||r.cases===null?'Cases unknown':r.cases+' declared cases'}</small></button>`).join('')||'<p>No matching candidates.</p>';$('#candidate-more').hidden=labLimit>=rs.length}
function candidateFill(r){if(!r)return '#454c4a';switch($('#candidate-measure').value){case'education':return eduColors[eduLevel(r.education)]||'#454c4a';case'gender':return r.gender==='Female'?'#d68cff':'#454c4a';case'cases':return r.cases===undefined||r.cases===null?'#454c4a':r.cases===0?'#26d9aa':r.cases<5?'#ffbd39':'#ff536f';case'penalty':return r.cases===undefined||r.cases===null?'#454c4a':r.cases*caseWeight()===0?'#26d9aa':r.cases*caseWeight()<5?'#ffbd39':'#ff536f'}}
function caseWeight(){return Math.max(0,Math.min(10,Number($('#case-weight').value)||0))}
function renderCandidateMap(rs){const party=$('#candidate-party').value,items=Object.values(labState.seats).map(s=>{const focus=s.winner;return {s,r:party?rs.filter(r=>r.seatId===s.id).sort((a,b)=>(b.votes||0)-(a.votes||0))[0]:focus?rs.find(r=>r.seatId===s.id&&nameKey(r.resultName||r.name)===nameKey(focus.name)):null}});const mode=$('#candidate-measure').value;$('#candidate-map-legend').innerHTML=mode==='education'?'School <span class="legend-arrow">→</span> Graduate <span class="legend-arrow">→</span> Postgraduate / doctorate · grey = unknown':mode==='gender'?'Purple = recorded female · grey = gender not imported':mode==='penalty'?`Green = 0 case penalty · amber = under 5 points deducted · red = 5+ · grey = unknown. Weight ${caseWeight()} per case.`:'Green = 0 declared · amber = 1–4 · red = 5+ · grey = unknown';const mapped=Object.keys(labState.map).length;$('#candidate-map').hidden=!mapped;$('#candidate-map-tiles').hidden=!!mapped;if(mapped){$('#candidate-map').setAttribute('viewBox',bounds(Object.values(labState.map)));$('#candidate-map').innerHTML=items.filter(x=>labState.map[x.s.id]).map(({s,r})=>`<path d="${labState.map[s.id]}" fill="${candidateFill(r)}" ${r?`data-profile="${esc(r.uid)}" tabindex="0" role="button" aria-label="${esc(s.name)}, ${esc(r.name)}"`:''} class="${r?.uid===labSelected?'selected':''}"><title>${esc(s.name)} · ${r?esc(r.name)+' · '+esc(mode==='education'?r.education||'unknown':mode==='gender'?r.gender||'unknown':r.cases===undefined||r.cases===null?'unknown':r.cases+' declared cases'):'No linked background record'}</title></path>`).join('')}else $('#candidate-map-tiles').innerHTML=items.map(({s,r})=>`<button ${r?`data-profile="${r.uid}"`:''} style="background:${candidateFill(r)}">${esc(s.id)}</button>`).join('')}
function renderCandidateProfile(r){if(!r){$('#candidate-profile').innerHTML='<h2>No candidate selected</h2>';return}const b=r.bio,missing='Not reviewed',penalty=Number.isInteger(r.cases)?'−'+(r.cases*caseWeight()):'Unavailable';$('#candidate-profile').innerHTML=`<div class="eyebrow">${r.year} / ${esc(r.seat)}</div><h2>${esc(title(r.name))}</h2><div>${chip(r.party)} <button class="text-link" data-explain-party="${esc(r.party)}">About this party ↗</button></div><p>${esc(b?.bio||`${title(r.name)} is listed as a ${DATA.partyNames[r.party]||r.party} candidate for ${title(r.seat)} in ${r.year}. ${r.source?'The fields below come from the election affidavit summary.':'A researched biography has not yet been imported.'}`)}</p><dl class="profile-facts"><dt>Highest education</dt><dd>${esc(r.education||b?.qualification||'Not imported')}</dd><dt>Institution / qualification</dt><dd>${esc([b?.institution,b?.qualification].filter(Boolean).join(' · ')||'Institution details not imported')}</dd><dt>Gender</dt><dd>${esc(r.gender||'Not imported')}</dd><dt>Religion / caste</dt><dd>Not collected</dd><dt>Declared criminal cases</dt><dd>${Number.isInteger(r.cases)?r.cases+' · election-time declaration':'Not imported'}</dd><dt>Convictions</dt><dd>${missing}</dd><dt>Cases involving crimes against women</dt><dd>${missing}</dd><dt>Sexual-misconduct allegations / response</dt><dd>${missing}</dd><dt>Experimental case penalty</dt><dd>${penalty}${Number.isInteger(r.cases)?` = −(${r.cases} × ${caseWeight()})`:''}<small>Case-only calculation; other review fields incomplete.</small></dd></dl>${b?.note?`<p class="note">${esc(b.note)}</p>`:''}<p class="note">Pending cases are unproven allegations. A zero in a historical affidavit is not a present-day clearance. No deduction is assigned for an unreviewed allegation.</p><div class="profile-sources">${r.source?`<a href="${esc(r.source)}" target="_blank" rel="noopener">${r.year} ADR / affidavit source ↗</a>`:''}${b?`<a href="${esc(b.source)}" target="_blank" rel="noopener">Biography source ↗</a>`:''}${b?.educationSource?`<a href="${esc(b.educationSource)}" target="_blank" rel="noopener">Qualification source ↗</a>`:''}</div>`}
function renderManifestos(){const level=$('#promise-level').value,term=DATA.manifestos.find(t=>t.id===$('#promise-term').value);if(level!=='state'){for(const id of ['promise-summary','promise-ledger'])$('#'+id).innerHTML='';$('#promise-context').innerHTML='<h2>This level is not imported yet.</h2><p>National and local commitments need their own manifesto, responsible government, term and delivery evidence. State promises are not used as a substitute.</p>';return}const all=term.promises,assessed=all.filter(p=>!['Not assessed','Not in government'].includes(p.status));$('#promise-summary').innerHTML=statCard('Inventory',all.length+' selected','Partial ledger · complete manifesto not yet indexed')+statCard('Evidence reviewed',assessed.length+'/'+all.length,'Dated checks; not a whole-manifesto rate')+statCard('Verified completion','Not calculated','Full denominator and delivery audit required')+statCard('On-track percentage','Not calculated','Needs deadlines and progress evidence');$('#promise-context').innerHTML=`<h3>${esc(term.state)} · ${term.year} · ${esc(term.coalition)}</h3><p>${esc(term.role)}. ${esc(term.note)}</p>${term.claim?`<div class="claim-box"><strong>${term.claim.value}% · ${esc(term.claim.label)}</strong><p>${esc(term.claim.note)} ${esc(term.claim.date)}.</p><a href="${esc(term.claim.source)}" target="_blank" rel="noopener">Read claim and context ↗</a></div>`:''}`;const filter=$('#promise-status').value;$('#promise-ledger').innerHTML=all.filter(p=>filter==='all'||p.status===filter).map(p=>`<article class="promise-card"><div class="promise-top"><span class="record-tag">${esc(p.id)} · ${esc(p.category)}</span><strong class="status-pill ${p.status==='Not assessed'?'unknown':''}">${esc(p.status)}</strong></div><h2>${esc(p.text)}</h2><div class="promise-flow"><span>Manifesto commitment</span><b>→</b><span>${esc(p.status)}</span></div><p>${esc(p.evidence)}</p>${p.target?`<p class="numeric-target">₹${p.observed.toLocaleString()} observed <span>→</span> ₹${p.target.toLocaleString()} promised <small>Amount comparison, not a completion percentage.</small></p>`:''}<div class="promise-sources"><a href="${esc(p.promiseSource)}" target="_blank" rel="noopener">Promise source ↗</a>${p.evidenceUrl?`<a href="${esc(p.evidenceUrl)}" target="_blank" rel="noopener">Progress evidence ↗</a>`:''}<small>${p.asof?'Evidence as of '+esc(p.asof):'No delivery assessment yet'}</small></div></article>`).join('')||'<p>No commitments match this status.</p>'}
$('#directory-state').addEventListener('change',()=>{directoryYears();renderGuide()});$('#directory-year').addEventListener('change',()=>renderGuide());$('#directory-search').addEventListener('input',()=>renderGuide());
$('#candidates-nav').addEventListener('click',()=>{researchPage('candidate-lab','candidates-nav','#candidates');if(!$('#candidate-state').options.length){setupGeography($('#candidate-state'));$('#candidate-state').value=contextCode==='IN'?'KL':contextCode;candidateYears()}else renderCandidates()});
$('#candidate-state').addEventListener('change',candidateYears);$('#candidate-year').addEventListener('change',()=>loadCandidateElection());for(const id of ['candidate-party','candidate-measure','candidate-coverage'])$('#'+id).addEventListener('change',()=>{labLimit=40;renderCandidates()});$('#candidate-search').addEventListener('input',()=>{labLimit=40;renderCandidates()});$('#case-weight').addEventListener('input',()=>renderCandidates());$('#candidate-more').addEventListener('click',()=>{labLimit+=40;renderCandidates()});
$('#promises-nav').addEventListener('click',()=>{researchPage('manifesto-view','promises-nav','#manifestos');if(!$('#promise-term').options.length)$('#promise-term').innerHTML=DATA.manifestos.map(t=>`<option value="${t.id}">${t.year} · ${t.coalition} · ${t.role.split(' · ')[0]}</option>`).join('');renderManifestos()});for(const id of ['promise-term','promise-status','promise-level'])$('#'+id).addEventListener('change',()=>renderManifestos());
document.addEventListener('click',e=>{const review=e.target.closest('[data-review-name]');if(review){$('#candidates-nav').click();$('#candidate-state').value=review.dataset.reviewState;candidateYears();$('#candidate-year').value=review.dataset.reviewYear;loadCandidateElection();const found=labRows.find(r=>nameKey(r.resultName||r.name)===nameKey(review.dataset.reviewName));if(found){labSelected=found.uid;renderCandidateProfile(found);renderCandidateMap(filteredLab())}else{$('#candidate-search').value=review.dataset.reviewName;renderCandidates()}$('#candidate-profile').scrollIntoView({behavior:'smooth',block:'start'});return}const p=e.target.closest('[data-profile]');if(p){labSelected=p.dataset.profile;renderCandidateProfile(filteredLab().find(r=>r.uid===labSelected));renderCandidateMap(filteredLab());return}const b=e.target.closest('[data-explain-party]');if(b){$('#guide-nav').click();$('#directory-state').value='ALL';directoryYears();$('#directory-search').value=b.dataset.explainParty;renderGuide()}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('svg [data-profile]')){e.preventDefault();labSelected=e.target.dataset.profile;renderCandidateProfile(filteredLab().find(r=>r.uid===labSelected));renderCandidateMap(filteredLab())}});

// Kerala 2021: official roster, declared affidavit records, explicit uncertainty.
const educationPoints={'Illiterate':0,'Literate':10,'5th Pass':20,'8th Pass':30,'10th Pass':40,'12th Pass':60,'Graduate':80,'Graduate Professional':80,'Post Graduate':90,'Doctorate':100};
function auditScore(r){const w=Math.max(0,Math.min(100,Number($('#case-weight').value)||0))/100;const e=educationPoints[r.education],c=r.cases,v=r.convictions,f=r.womenCases;const known=[c,v,f].every(Number.isInteger);const deduction=(Number.isInteger(c)?Math.min(20,2*c):0)+(Number.isInteger(v)?Math.min(60,25*v):0)+(Number.isInteger(f)?Math.min(30,10*f):0);const hi=Math.max(0,100-deduction),lo=known?hi:Math.max(0,hi-(Number.isInteger(c)?0:20)-(Number.isInteger(v)?0:60)-(Number.isInteger(f)?0:30));const low=w*lo+(1-w)*(e??0),high=w*hi+(1-w)*(e??100);return {low,high,point:(low+high)/2,complete:known&&e!==undefined,record:known?hi:null};}
function scoreText(r){const s=auditScore(r);return s.complete?s.point.toFixed(1):`${s.point.toFixed(1)} provisional · ${s.low.toFixed(0)}–${s.high.toFixed(0)}`}
const previousRenderCandidates=renderCandidates;
renderCandidates=function(){previousRenderCandidates();if(labState.code!=='KL'||labState.year!==2021)return;const rs=filteredLab(),all=labRows.map(r=>auditScore(r).point).sort((a,b)=>a-b),median=all[Math.floor(all.length/2)];$('#candidate-summary').innerHTML=statCard('Official contestants',rs.length,'All nominees, not just winners')+statCard('Affidavit summaries',rs.filter(r=>r.cases!==null).length+'/'+rs.length,'Missing summaries remain in the denominator')+statCard('Complete score inputs',rs.filter(r=>auditScore(r).complete).length+'/'+rs.length,'Incomplete records have score intervals')+statCard('Women / third gender',rs.filter(r=>r.gender==='Female').length+' / '+rs.filter(r=>r.gender==='Third gender').length,'Official ECI gender; full roster coverage')+statCard('SC / ST nominees',rs.filter(r=>r.electoralCategory==='SC').length+' / '+rs.filter(r=>r.electoralCategory==='ST').length,'Electoral categories; General does not mean upper caste')+statCard('Kerala median background index',median.toFixed(1)+'/100','Provisional midpoints included; not an objective merit threshold');
$('#candidate-count').innerHTML=`${rs.length} nominees · score weight ${$('#case-weight').value}% case record / ${100-Number($('#case-weight').value)}% education. ${DATA.candidateReview.coverage.affidavitSummaries}/957 affidavit summaries linked; ${DATA.candidateReview.coverage.detailedReview}/957 detailed declarations parsed. 2021 declarations are historical, not current court clearance.`;
let host=$('#party-scores');if(!host){host=document.createElement('section');host.id='party-scores';$('#candidate-summary').after(host)}const groups=new Map();for(const r of labRows){const g=groups.get(r.party)||[];g.push(r);groups.set(r.party,g)}host.innerHTML='<h2>Compare parties’ candidate backgrounds</h2><p>Equal weight per nominee · line = Kerala candidate median · pale span = uncertainty from missing inputs. Small parties can move sharply with one candidate. Independents are a separate cohort.</p>'+[...groups].map(([p,rows])=>{const ss=rows.map(auditScore),mean=k=>ss.reduce((n,s)=>n+s[k],0)/ss.length;return {p,rows,low:mean('low'),high:mean('high'),point:mean('point'),complete:ss.filter(s=>s.complete).length}}).sort((a,b)=>b.point-a.point).map(g=>`<button class="score-row" data-score-party="${esc(g.p)}"><span>${esc(g.p)} <small>${g.rows.length} nominees · ${g.complete} complete</small></span><span class="score-track"><i style="left:${g.low}%;width:${g.high-g.low}%"></i><b style="left:${g.point}%"></b><em style="left:${median}%"></em></span><strong>${g.complete===g.rows.length?g.point.toFixed(1):g.low.toFixed(1)+'–'+g.high.toFixed(1)} <small>${g.complete===g.rows.length?'Complete declared inputs':'Provisional midpoint '+g.point.toFixed(1)}</small></strong></button>`).join('');
$('#candidate-roster').innerHTML=[...rs].sort((a,b)=>auditScore(b).point-auditScore(a).point).slice(0,labLimit).map(r=>`<button class="roster-card ${r.uid===labSelected?'active':''}" data-profile="${esc(r.uid)}">${chip(r.party)}<h3>${esc(title(r.name))}</h3><p>${esc(title(r.seat))}</p><strong>${scoreText(r)} / 100</strong><small>${esc(r.education||'Education unknown')} · ${r.cases??'?'} declared cases · ${r.convictions??'?'} declared convictions</small></button>`).join('');};
const previousProfile=renderCandidateProfile;
renderCandidateProfile=function(r){if(!r||r.state!=='KL'||r.year!==2021)return previousProfile(r);const s=auditScore(r);$('#candidate-profile').innerHTML=`<div class="eyebrow">Kerala 2021 · ${esc(r.seat)}</div><h2>${esc(title(r.name))}</h2>${chip(r.party)}<h2>${scoreText(r)} / 100</h2><p>${s.complete?'Complete declared score inputs':'Provisional midpoint; interval covers missing inputs'}. ${$('#case-weight').value}% record / ${100-Number($('#case-weight').value)}% education.</p><p>${esc(r.bio?.bio||'Candidate in the official 2021 Assembly roster. Background facts below refer to election-time declarations.')}</p><dl class="profile-facts"><dt>Education</dt><dd>${esc(r.education||'Unknown')} · ${educationPoints[r.education]??'?'} / 100</dd><dt>Qualification / institution</dt><dd>${esc(r.educationDetail||r.bio?.institution||'No detailed qualification recovered')}</dd><dt>Age / gender</dt><dd>${r.age} · ${esc(r.gender)}</dd><dt>Electoral category</dt><dd>${esc(r.electoralCategory)}<small>Not a full caste or sub-caste classification.</small></dd><dt>Religion</dt><dd>${esc(r.religion||'Not established from reviewed sources')}</dd><dt>Reported caste / community</dt><dd>${esc(r.caste||'Not established')}<small>${esc(r.identityReview)}</small></dd><dt>Declared cases</dt><dd>${r.cases??'Unknown'}</dd><dt>Declared convictions</dt><dd>${r.convictions??'Unknown'}</dd><dt>Pending cases</dt><dd>${r.pendingCases??'Unknown'}</dd><dt>Women / sexual-offence code flags</dt><dd>${r.womenCases??'Incomplete case coverage'}<small>${esc(r.womenCaseNote)}</small></dd><dt>Off-affidavit allegations</dt><dd>${esc(r.allegationReview)}</dd></dl><h3>Read the case context</h3>${r.caseDetails.length?r.caseDetails.map(c=>`<details class="case-detail"><summary>${esc(c.status)} · ${esc(c.caseNo||c.fir||'Case declaration')}</summary><p>${esc(c.court||'')} · IPC ${esc(c.ipc||'not listed')} · ${esc(c.otherActs||'')}</p>${c.sentence?`<p>Sentence declared: ${esc(c.sentence)} · ${esc(c.convictionDate||'')}</p>`:''}<p>Appeal: ${esc(c.appeal||'Not specified')} ${esc(c.appealStatus||'')}</p></details>`).join(''):'<p>No individual case rows recovered. This is zero only where the affidavit explicitly declares zero cases.</p>'}<p class="note">Pending allegations are not convictions. The index treats declared protest cases and other cases alike at its base deduction; inspect offence context. Appeals and changes after 2021 are not resolved by this archive.</p><div class="profile-sources"><a href="${esc(r.demographicSource)}" target="_blank" rel="noopener">Official ECI roster ↗</a>${r.source?`<a href="${esc(r.source)}" target="_blank" rel="noopener">2021 affidavit ↗</a>`:''}${r.casteSource?`<a href="${esc(r.casteSource)}" target="_blank" rel="noopener">Community reporting ↗</a>`:''}</div>`;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-score-party]');if(b){$('#candidate-party').value=b.dataset.scoreParty;labLimit=40;renderCandidates();$('#candidate-roster').scrollIntoView({behavior:'smooth'})}});
const gpsPositions={BJP:7.68965517,INC:4.6,AITC:3.52,BJD:4.588235,TDP:5.714286,ADMK:5.058824,SHS:6.5,TRS:4.9375,YSRCP:4.363636};
const originalGuide=renderGuide;
renderGuide=function(){originalGuide();let host=$('#party-spectrum');if(!host){host=document.createElement('section');host.id='party-spectrum';$('#guide-lanes').before(host)}const parties=new Set(directorySnapshots().filter(Boolean).flatMap(s=>Object.values(s.seats).flatMap(seat=>seat.candidates.map(c=>c.party))).filter(p=>p!=='NOTA'&&p!=='IND'));const measured=[...parties].filter(p=>gpsPositions[p]!==undefined).sort((a,b)=>gpsPositions[a]-gpsPositions[b]);const values=measured.map(p=>gpsPositions[p]),median=values.length?(values[Math.floor((values.length-1)/2)]+values[Math.floor(values.length/2)])/2:null;host.innerHTML=`<h2>Where do the parties sit?</h2><p>Left <span class="legend-arrow">←</span> general political orientation <span class="legend-arrow">→</span> Right. Expert-survey positions are from 2019, not a claim about today’s alliances. Shaded bands for CPI, CPI(M), SP and DMK are broad editorial orientation summaries from their sourced introductions, not survey estimates or confidence intervals. The vertical line marks the median of the measured parties in this selection; 5 is the scale midpoint.</p><div class="spectrum-labels"><b>0 · Left</b><span>5 · Centre</span><b>Right · 10</b></div>${[...parties].filter(p=>['CPI','CPI(M)','SP','DMK'].includes(p)).map(p=>`<div class="score-row"><span>${esc(p)}<small>Editorial band</small></span><span class="score-track"><i style="left:${p==='DMK'?25:p==='SP'?15:0}%;width:30%"></i>${median!==null?`<em style="left:${median*10}%"></em>`:''}</span><strong>${p==='DMK'?'Centre-left':'Left'}<small>Broad orientation</small></strong></div>`).join('')}${measured.map(p=>`<button class="score-row" data-explain-party="${esc(p)}"><span>${esc(p)}<small>GPS 2019 · Expert score</small></span><span class="score-track"><b style="left:${gpsPositions[p]*10}%;background:${color(p)}"></b>${median!==null?`<em style="left:${median*10}%"></em>`:''}</span><strong>${gpsPositions[p].toFixed(1)}</strong></button>`).join('')||'<p>No directly matched survey position for these parties.</p>'}<p>${median!==null?'Selected-party median: '+median.toFixed(1)+'. ':''}<a href="https://www.globalpartysurvey.org/download-data" target="_blank" rel="noopener">Global Party Survey 2019</a> · V4 general left–right, 0–10. <a href="https://grinnell-statistics.github.io/sta-209-s23-wells/projects/global-party-survey/global-party-survey.csv" target="_blank" rel="noopener">Public university data mirror</a>.</p><details><summary>${[...parties].filter(p=>gpsPositions[p]===undefined).length} party labels without a directly matched survey score</summary><p>${[...parties].filter(p=>gpsPositions[p]===undefined).sort().map(esc).join(' · ')}</p><p>The Communist entry has an ambiguous name/identifier and is not automatically assigned to CPI or CPI(M). The sourced introductions below identify both as left-wing. Regional and minority representation are not, by themselves, left–right positions. Unmeasured parties remain visible rather than receiving invented coordinates.</p></details>`;};
const oldManifestos=renderManifestos;
renderManifestos=function(){const term=DATA.manifestos.find(t=>t.id===$('#promise-term').value);if(!term)return;const statuses=[...new Set(DATA.manifestos.flatMap(t=>t.promises.map(p=>p.status)))],selected=$('#promise-status').value;$('#promise-status').innerHTML='<option value="all">All judgments</option>'+statuses.map(s=>`<option>${esc(s)}</option>`).join('');$('#promise-status').value=statuses.includes(selected)?selected:'all';oldManifestos();if($('#promise-level').value!=='state')return;const eligible=term.promises.filter(p=>!['Not in government','Not yet due'].includes(p.status)),delivered=eligible.filter(p=>p.status==='Delivered').length,partial=eligible.filter(p=>p.status==='Partly delivered').length;$('#promise-summary').innerHTML=statCard('Reviewed inventory',term.promises.length+' selected','Not the complete manifesto')+statCard('Fully delivered',eligible.length?Math.round(100*delivered/eligible.length)+'%':'Not applicable',`${delivered}/${eligible.length} eligible selected pledges · unknown delivery stays in denominator`)+statCard('Partly delivered',partial,'Activity verified; full target not established')+statCard('Outcome rule','Evidence first','Not demonstrated ≠ proved failure. Opposition and future-due pledges excluded.');};
const oldFill=candidateFill;candidateFill=function(r){if($('#candidate-measure').value==='score'){if(!r||r.state!=='KL'||r.year!==2021)return '#606761';const s=auditScore(r);return !s.complete?'#808782':s.point>=80?'#28e4b3':s.point>=60?'#43bcff':s.point>=40?'#ffbb36':'#fb5482'}return oldFill(r)};
const oldCandidateMap=renderCandidateMap;renderCandidateMap=function(rs){oldCandidateMap(rs);if($('#candidate-measure').value==='score')$('#candidate-map-legend').textContent='Index: green ≥80 · blue 60–79 · amber 40–59 · pink <40 · grey = incomplete / unscored. All nominees remain in party averages.';if($('#candidate-measure').value==='gender')$('#candidate-map-legend').textContent='Purple = recorded female · grey = male, third gender or unknown; select a candidate to see the exact official category.'};

