country();const requestedGuide=false,requestedCandidates=false,requestedManifestos=false;const voteHash=new URLSearchParams(location.hash.slice(1));if(voteHash.get('year')){const code=voteHash.get('state');if(code==='LS')nationalYear=voteHash.get('year');else if(versionFor(code,voteHash.get('year')))activeVersions[code]=versionFor(code,voteHash.get('year'))}if(voteHash.get('state')||initialView||['#guide','#candidates','#manifestos'].includes(location.hash))selectState(voteHash.get('state')||'LS',voteHash.get('seat'),false);else openHome();if(requestedGuide)$('#guide-nav').click();if(requestedCandidates)$('#candidates-nav').click();if(requestedManifestos)$('#promises-nav').click();
